#!/usr/bin/env python3
"""Extract human-readable transcript from a Claude Code JSONL session log."""
import json
import sys
from pathlib import Path

SRC = Path("/Users/aditya/.claude/projects/-Users-aditya-Documents-Icebreaker/192ad776-f6a5-4f9d-8b58-fe195ac95d76.jsonl")
OUT_DIR = Path("/Users/aditya/Documents/Icebreaker")
FULL = OUT_DIR / "session_192ad776_transcript_full.md"
RECENT = OUT_DIR / "session_192ad776_transcript_recent.md"

def flatten_content(content):
    """Pull human-visible text out of a message.content (string or list)."""
    if isinstance(content, str):
        return content
    if not isinstance(content, list):
        return ""
    out = []
    for block in content:
        if not isinstance(block, dict):
            continue
        t = block.get("type")
        if t == "text":
            txt = block.get("text", "")
            if txt:
                out.append(txt)
        elif t == "thinking":
            # skip internal thinking from main render — too noisy
            continue
        elif t == "tool_use":
            name = block.get("name", "?")
            inp = block.get("input", {})
            # render only command/file_path-ish fields, briefly
            preview = {}
            for k in ("command", "file_path", "path", "description", "old_string", "new_string", "prompt", "skill", "url"):
                if k in inp:
                    v = inp[k]
                    if isinstance(v, str) and len(v) > 400:
                        v = v[:400] + "…[truncated]"
                    preview[k] = v
            out.append(f"[tool_use {name}] " + json.dumps(preview, ensure_ascii=False))
        elif t == "tool_result":
            tc = block.get("content")
            txt = flatten_content(tc) if not isinstance(tc, str) else tc
            if txt:
                if len(txt) > 600:
                    txt = txt[:600] + "…[truncated]"
                out.append(f"[tool_result] {txt}")
    return "\n".join(s for s in out if s)


def iter_events(path):
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                yield json.loads(line)
            except json.JSONDecodeError:
                continue


def main():
    turns = []  # list of (timestamp, role, text)
    for d in iter_events(SRC):
        t = d.get("type")
        if t not in ("user", "assistant"):
            continue
        if d.get("isMeta"):
            continue
        if d.get("isSidechain"):
            continue  # skip subagent chatter
        msg = d.get("message", {})
        role = msg.get("role") or t
        content = msg.get("content")
        text = flatten_content(content)
        if not text.strip():
            continue
        # skip the local-command-caveat boilerplate
        if "<local-command-caveat>" in text and len(text) < 400:
            continue
        ts = d.get("timestamp", "")
        turns.append((ts, role, text))

    # ---- FULL TRANSCRIPT ----
    with open(FULL, "w") as f:
        f.write(f"# Session 192ad776 — full transcript\n\n")
        f.write(f"Source: `{SRC.name}`  \n")
        f.write(f"Events: {len(turns)} text turns (sidechain / meta / boilerplate stripped)\n\n")
        f.write("---\n\n")
        for ts, role, text in turns:
            f.write(f"## {role} — {ts}\n\n")
            f.write(text.rstrip() + "\n\n")

    # ---- RECENT TAIL (last ~40 turns + special focus on user prompts) ----
    tail = turns[-80:] if len(turns) > 80 else turns
    user_prompts_recent = [t for t in turns[-200:] if t[1] == "user"][-20:]
    with open(RECENT, "w") as f:
        f.write("# Session 192ad776 — recent pending-work context\n\n")
        f.write("Hand this to a fresh Claude Code chat to resume where the broken session left off.\n\n")
        f.write("---\n\n## Last 20 user prompts (chronological)\n\n")
        for ts, _, text in user_prompts_recent:
            preview = text.strip()
            if len(preview) > 1500:
                preview = preview[:1500] + "…[truncated]"
            f.write(f"### {ts}\n\n{preview}\n\n")
        f.write("---\n\n## Last 80 turns (full text)\n\n")
        for ts, role, text in tail:
            f.write(f"### {role} — {ts}\n\n")
            f.write(text.rstrip() + "\n\n")

    print(f"Wrote {FULL}  ({FULL.stat().st_size:,} bytes)")
    print(f"Wrote {RECENT}  ({RECENT.stat().st_size:,} bytes)")
    print(f"Total text turns extracted: {len(turns)}")

if __name__ == "__main__":
    main()

