#!/usr/bin/env python3
"""Pull the full compact-summary message + last assistant response for resume."""
import json
from pathlib import Path

SRC = Path("/Users/aditya/.claude/projects/-Users-aditya-Documents-Icebreaker/192ad776-f6a5-4f9d-8b58-fe195ac95d76.jsonl")
OUT = Path("/Users/aditya/Documents/Icebreaker/session_192ad776_RESUME.md")

def flatten(content):
    if isinstance(content, str):
        return content
    if not isinstance(content, list):
        return ""
    parts = []
    for b in content:
        if isinstance(b, dict) and b.get("type") == "text":
            parts.append(b.get("text", ""))
    return "\n".join(parts)

compact_summary = None
last_assistant_text = None
last_user_real = None  # last non-meta user message before the API error storm

with open(SRC) as f:
    for line in f:
        try:
            d = json.loads(line)
        except:
            continue
        if d.get("type") not in ("user", "assistant"):
            continue
        if d.get("isSidechain"):
            continue
        msg = d.get("message", {})
        role = msg.get("role")
        text = flatten(msg.get("content"))
        if not text.strip():
            continue
        if role == "user":
            if "This session is being continued from a previous conversation" in text:
                compact_summary = text
            if not text.startswith("<") and not text.startswith("[tool_result]") and len(text) > 20:
                last_user_real = text
        elif role == "assistant":
            if text.strip():
                last_assistant_text = text

with open(OUT, "w") as f:
    f.write("# Resume context for session 192ad776\n\n")
    f.write("Paste this into a fresh Claude Code chat (or attach the file) to continue where the broken session left off.\n\n")
    f.write("**Working directory:** `/Users/aditya/Documents/Icebreaker`  \n")
    f.write("**Branch:** `feature/phase1-mcpd`  \n\n")
    f.write("---\n\n## Full compact-summary the previous Claude wrote before the crash\n\n")
    if compact_summary:
        f.write(compact_summary.strip() + "\n\n")
    else:
        f.write("_(not found)_\n\n")
    f.write("---\n\n## Last meaningful user message before the API-error storm\n\n")
    if last_user_real:
        f.write(last_user_real.strip() + "\n\n")
    else:
        f.write("_(not found)_\n\n")
    f.write("---\n\n## Last assistant text output (whatever it managed to say before breaking)\n\n")
    if last_assistant_text:
        f.write(last_assistant_text.strip() + "\n")

print(f"Wrote {OUT} ({OUT.stat().st_size:,} bytes)")
print(f"Has compact_summary: {bool(compact_summary)}")
print(f"Has last_user_real: {bool(last_user_real)}")
print(f"Has last_assistant_text: {bool(last_assistant_text)}")

