{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://icebreaker.local/schemas/intent/v1",
  "title": "IntentObject",
  "description": "Validated intent passed from the Controller to the Privileged Brain. Never contains raw user text — only structured, schema-validated fields.",
  "type": "object",
  "required": ["intent_id", "action", "target", "params", "reason", "risk_level"],
  "additionalProperties": false,
  "properties": {
    "intent_id": {
      "type": "string",
      "format": "uuid",
      "description": "Opaque UUID reference. This is the ONLY thing the Privileged Brain receives — never raw user text."
    },
    "action": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9_]*\\.[a-z][a-z0-9_]*$",
      "maxLength": 64,
      "description": "MCP tool name in the form 'module.method'. Must match an entry in mcpd's tools/list catalogue."
    },
    "target": {
      "type": "string",
      "maxLength": 512,
      "pattern": "^[^;&|`$<>\\x00-\\x1f]*$",
      "description": "Primary target of the action (e.g. path, service name, PID). Shell metacharacters are forbidden."
    },
    "params": {
      "type": "object",
      "description": "Tool-specific parameters. Validated against the tool's JSON Schema from mcpd.",
      "additionalProperties": {
        "oneOf": [
          { "type": "string",  "maxLength": 1024, "pattern": "^[^;&|`$<>\\x00-\\x1f]*$" },
          { "type": "number" },
          { "type": "boolean" },
          { "type": "null" }
        ]
      }
    },
    "reason": {
      "type": "string",
      "enum": ["user_requested", "ai_autonomous", "scheduled"],
      "description": "Why this intent was generated. Affects audit log and HITL display."
    },
    "risk_level": {
      "type": "string",
      "enum": ["read_only", "low", "medium", "high", "critical"],
      "description": "Risk tier. Determines HITL behavior: read_only/low=auto, medium=notify, high/critical=block+prompt."
    },
    "schema_version": {
      "type": "string",
      "pattern": "^\\d+\\.\\d+\\.\\d+$",
      "description": "Version of the mcpd schema catalogue this intent was validated against."
    },
    "timestamp": {
      "type": "number",
      "description": "Unix timestamp (seconds) when the intent was created."
    }
  }
}

"""
intent_store.py — In-memory store that maps opaque UUID references to validated
Intent Objects. This is the ONLY place where the raw Intent Object lives after
it leaves the Quarantined Brain.

Security invariant (INV-1, INV-2):
  - The Privileged Brain receives ONLY the opaque intent_id string, never the
    Intent Object itself.
  - The Intent Object is fetched from this store only by the Controller and the
    QB verifier — never by the Privileged Brain.
  - Entries expire after TTL_SECONDS to bound memory and prevent stale replay.
"""

from __future__ import annotations

import threading
import time
import uuid
from dataclasses import dataclass, field
from typing import Optional


TTL_SECONDS = 300  # 5 minutes — long enough for HITL approval


@dataclass
class IntentEntry:
    intent: dict
    created_at: float = field(default_factory=time.time)

    def is_expired(self) -> bool:
        return (time.time() - self.created_at) > TTL_SECONDS


class IntentStore:
    """Thread-safe store of Intent Objects keyed by opaque UUID.

    Usage:
        store = IntentStore()
        ref_id = store.put(validated_intent_object)
        intent = store.get(ref_id)   # returns None if expired or unknown
        store.delete(ref_id)
    """

    def __init__(self) -> None:
        self._store: dict[str, IntentEntry] = {}
        self._lock = threading.Lock()

    def put(self, intent: dict) -> str:
        """Store a validated Intent Object and return an opaque UUID reference."""
        ref_id = str(uuid.uuid4())
        with self._lock:
            self._store[ref_id] = IntentEntry(intent=intent)
        return ref_id

    def get(self, ref_id: str) -> Optional[dict]:
        """Retrieve an Intent Object by reference ID. Returns None if unknown or expired."""
        with self._lock:
            entry = self._store.get(ref_id)
            if entry is None:
                return None
            if entry.is_expired():
                del self._store[ref_id]
                return None
            return entry.intent

    def delete(self, ref_id: str) -> None:
        with self._lock:
            self._store.pop(ref_id, None)

    def revise(self, original_ref_id: str, correction: dict) -> Optional[str]:
        """Apply a structured correction to an existing intent and store it as a new entry.

        The correction dict may contain a subset of top-level Intent Object fields to
        override (e.g. {"target": "/var/cache/apt"}).  Fields not present in correction
        are copied from the original intent unchanged.

        Returns a new opaque reference ID for the revised intent, or None if the
        original intent is unknown or expired.
        """
        original = self.get(original_ref_id)
        if original is None:
            return None

        revised = {**original, **correction}
        # Correction must not introduce new top-level keys not in the original
        extra_keys = set(revised.keys()) - set(original.keys())
        if extra_keys:
            raise ValueError(
                f"Correction introduced unknown Intent Object fields: {extra_keys}. "
                "Only fields present in the original schema are allowed (INV-2)."
            )

        return self.put(revised)

    def evict_expired(self) -> int:
        """Remove all expired entries. Returns count of entries evicted."""
        now = time.time()
        with self._lock:
            expired = [k for k, v in self._store.items() if v.is_expired()]
            for k in expired:
                del self._store[k]
        return len(expired)

    def __len__(self) -> int:
        with self._lock:
            return len(self._store)


# Module-level singleton — the Controller imports this directly
_store = IntentStore()


def put(intent: dict) -> str:
    return _store.put(intent)


def get(ref_id: str) -> Optional[dict]:
    return _store.get(ref_id)


def delete(ref_id: str) -> None:
    _store.delete(ref_id)


def revise(original_ref_id: str, correction: dict) -> Optional[str]:
    return _store.revise(original_ref_id, correction)


def evict_expired() -> int:
    return _store.evict_expired()

#!/usr/bin/env python3
"""
risk_classifier.py — Tier 0–3 risk classification for Intent Objects.

Tiers:
  Tier 0 — Read-only operations. Auto-execute. No prompt. No notification.
  Tier 1 — Low-risk writes (user home dir, user services). Auto-execute + audit log.
  Tier 2 — Medium-risk (system services, package install). Auto-execute + notification.
  Tier 3 — High/critical (outside home dir, firewall, /etc/sudoers, /boot, /root). BLOCK + HITL prompt.

Usage:
  from risk_classifier import classify, Tier
  result = classify(intent)   # returns Tier + explanation
"""

from __future__ import annotations

import os
import re
from dataclasses import dataclass
from enum import IntEnum
from typing import Optional


class Tier(IntEnum):
    READ_ONLY = 0   # auto-execute, no UI
    LOW       = 1   # auto-execute + audit log
    MEDIUM    = 2   # auto-execute + notification
    HIGH      = 3   # BLOCK — requires explicit user approval


@dataclass
class ClassificationResult:
    tier: Tier
    reason: str
    reversible: bool
    blocked_pattern: Optional[str] = None

    @property
    def requires_hitl(self) -> bool:
        return self.tier == Tier.HIGH

    @property
    def auto_execute(self) -> bool:
        return self.tier in (Tier.READ_ONLY, Tier.LOW, Tier.MEDIUM)


# ── Tier 0: Always read-only — never need a prompt ───────────────────────────
_TIER0_TOOLS = frozenset({
    "system.status", "system.uptime", "system.cpu",
    "system.memory", "system.disk",
    "process.list", "process.inspect",
    "service.logs", "service.status",
    "fs.read", "fs.list", "fs.stat",
    "network.status", "network.interfaces", "network.dns",
    "package.list", "package.search", "package.info",
})

# ── Tier 3: Always block — these touch sensitive system locations ──────────────
_CRITICAL_PATHS = re.compile(
    r"(/boot|/etc/sudoers|/etc/shadow|/etc/passwd|/root|"
    r"/proc/sys/kernel|/dev/sd[a-z]|/dev/nvme|/sys/firmware)",
    re.IGNORECASE,
)

_DESTRUCTIVE_TOOLS = frozenset({
    "fs.delete",
    "network.firewall_flush",
    "network.firewall_delete",
    "package.purge",
})

_SYSTEM_WRITE_TOOLS = frozenset({
    "network.firewall_add",
    "network.firewall_modify",
    "package.install",
    "package.remove",
    "package.upgrade",
})

_USER_HOME = os.path.expanduser("~")


def _target_is_in_user_home(target: str) -> bool:
    """True if the target path is within the current user's home directory."""
    if not target:
        return False
    try:
        return os.path.abspath(target).startswith(_USER_HOME)
    except Exception:
        return False


def _target_is_critical(target: str) -> bool:
    """True if the target is a sensitive system path."""
    return bool(_CRITICAL_PATHS.search(target))


def classify(intent: dict) -> ClassificationResult:
    """
    Classify an Intent Object into a risk tier.

    Args:
        intent: Validated Intent Object (must pass JSON schema validation first).

    Returns:
        ClassificationResult with tier, reason, reversibility.
    """
    action     = intent.get("action", "")
    target     = intent.get("target", "")
    risk_level = intent.get("risk_level", "")

    # ── Explicit critical override from intent ────────────────────────────────
    if risk_level == "critical":
        return ClassificationResult(
            tier=Tier.HIGH,
            reason="Intent explicitly marked critical risk level",
            reversible=False,
        )

    # ── Tier 0: Pure read-only tools ─────────────────────────────────────────
    if action in _TIER0_TOOLS:
        return ClassificationResult(
            tier=Tier.READ_ONLY,
            reason=f"{action} is a read-only operation",
            reversible=True,
        )

    # ── Tier 3: Any operation touching a critical path ────────────────────────
    if _target_is_critical(target):
        return ClassificationResult(
            tier=Tier.HIGH,
            reason=f"Target '{target}' is a protected system path",
            reversible=False,
            blocked_pattern=_CRITICAL_PATHS.search(target).group(0) if _CRITICAL_PATHS.search(target) else None,
        )

    # ── Tier 3: Destructive tools ─────────────────────────────────────────────
    if action in _DESTRUCTIVE_TOOLS:
        return ClassificationResult(
            tier=Tier.HIGH,
            reason=f"{action} is a destructive operation — requires explicit approval",
            reversible=False,
        )

    # ── Tier 3: Writes outside user home ─────────────────────────────────────
    if action.startswith("fs.write") and target and not _target_is_in_user_home(target):
        return ClassificationResult(
            tier=Tier.HIGH,
            reason=f"fs.write to '{target}' is outside user home directory",
            reversible=False,
        )

    # ── Tier 3: Network/firewall mutations ───────────────────────────────────
    if action in _SYSTEM_WRITE_TOOLS:
        return ClassificationResult(
            tier=Tier.MEDIUM,
            reason=f"{action} modifies system-level configuration",
            reversible=action.startswith("package."),
        )

    # ── Tier 2: Service restarts for system (non-user) services ──────────────
    if action in ("service.restart", "service.stop", "service.start"):
        user_service = target.endswith(".service") and "/" in target
        if not user_service:
            return ClassificationResult(
                tier=Tier.MEDIUM,
                reason=f"Service operation on '{target}' — notify user",
                reversible=action != "service.stop",
            )

    # ── Tier 1: Low-risk writes inside user home ──────────────────────────────
    if action.startswith("fs.write") and _target_is_in_user_home(target):
        return ClassificationResult(
            tier=Tier.LOW,
            reason=f"Write to user home directory — auto-execute with audit",
            reversible=True,
        )

    # ── Default: Medium — log and notify ─────────────────────────────────────
    return ClassificationResult(
        tier=Tier.MEDIUM,
        reason=f"Unclassified action '{action}' — applying medium risk tier",
        reversible=True,
    )


# ── CLI for testing ───────────────────────────────────────────────────────────

if __name__ == "__main__":
    import json, sys

    test_cases = [
        {"action": "system.status",    "target": "",                    "params": {}, "reason": "user_requested", "risk_level": "read_only"},
        {"action": "fs.read",          "target": "/etc/hosts",          "params": {}, "reason": "user_requested", "risk_level": "read_only"},
        {"action": "fs.write",         "target": f"{_USER_HOME}/notes", "params": {}, "reason": "user_requested", "risk_level": "low"},
        {"action": "fs.write",         "target": "/etc/nginx/nginx.conf","params": {}, "reason": "user_requested", "risk_level": "medium"},
        {"action": "fs.delete",        "target": "/var/log/app.log",    "params": {}, "reason": "user_requested", "risk_level": "high"},
        {"action": "service.restart",  "target": "nginx",               "params": {}, "reason": "user_requested", "risk_level": "medium"},
        {"action": "package.install",  "target": "curl",                "params": {}, "reason": "user_requested", "risk_level": "medium"},
        {"action": "fs.write",         "target": "/boot/grub/grub.cfg", "params": {}, "reason": "user_requested", "risk_level": "critical"},
        {"action": "network.firewall_flush", "target": "",              "params": {}, "reason": "user_requested", "risk_level": "critical"},
    ]

    print(f"{'Action':<30} {'Target':<35} {'Tier':<12} {'HITL':<6} {'Reason'}")
    print("-" * 120)
    for intent in test_cases:
        result = classify(intent)
        print(
            f"{intent['action']:<30} "
            f"{intent['target']:<35} "
            f"Tier {result.tier} {result.tier.name:<6} "
            f"{'YES' if result.requires_hitl else 'no':<6} "
            f"{result.reason}"
        )

