1	/// JSON-RPC 2.0 server over stdin/stdout.
2	///
3	/// SECURITY INVARIANT (INV-3): This server communicates EXCLUSIVELY over stdio.
4	/// No TCP socket. No UNIX socket listener. No UDP. Nothing.
5	/// If you need to add a debug interface, use a named pipe with strict file permissions
6	/// accessible only to the current user — never a network listener.
7	use anyhow::Result;
8	use serde::{Deserialize, Serialize};
9	use serde_json::Value;
10	use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
11	use tracing::{error, info, warn};
12	
13	use crate::tools;
14	
15	#[derive(Debug, Deserialize)]
16	struct JsonRpcRequest {
17	    jsonrpc: String,
18	    id: Option<Value>,
19	    method: String,
20	    #[serde(default)]
21	    params: Value,
22	}
23	
24	#[derive(Debug, Serialize)]
25	struct JsonRpcResponse {
26	    jsonrpc: String,
27	    id: Value,
28	    #[serde(skip_serializing_if = "Option::is_none")]
29	    result: Option<Value>,
30	    #[serde(skip_serializing_if = "Option::is_none")]
31	    error: Option<JsonRpcError>,
32	}
33	
34	#[derive(Debug, Serialize)]
35	struct JsonRpcError {
36	    code: i32,
37	    message: String,
38	    #[serde(skip_serializing_if = "Option::is_none")]
39	    data: Option<Value>,
40	}
41	
42	impl JsonRpcResponse {
43	    fn ok(id: Value, result: Value) -> Self {
44	        Self { jsonrpc: "2.0".into(), id, result: Some(result), error: None }
45	    }
46	
47	    fn err(id: Value, code: i32, message: impl Into<String>) -> Self {
48	        Self {
49	            jsonrpc: "2.0".into(),
50	            id,
51	            result: None,
52	            error: Some(JsonRpcError { code, message: message.into(), data: None }),
53	        }
54	    }
55	}
56	
57	pub async fn run_stdio_server() -> Result<()> {
58	    let stdin = tokio::io::stdin();
59	    let stdout = tokio::io::stdout();
60	    let mut reader = BufReader::new(stdin);
61	    let mut writer = stdout;
62	    let mut line = String::new();
63	
64	    info!("Listening on stdin for JSON-RPC requests");
65	
66	    loop {
67	        line.clear();
68	        let bytes_read = reader.read_line(&mut line).await?;
69	
70	        if bytes_read == 0 {
71	            info!("stdin closed — shutting down");
72	            break;
73	        }
74	
75	        let trimmed = line.trim();
76	        if trimmed.is_empty() {
77	            continue;
78	        }
79	
80	        let started = std::time::Instant::now();
81	        let response = match serde_json::from_str::<JsonRpcRequest>(trimmed) {
82	            Err(e) => {
83	                warn!("Parse error: {}", e);
84	                let resp = JsonRpcResponse::err(Value::Null, -32700, format!("Parse error: {}", e));
85	                crate::audit::log_intent(
86	                    "<parse_error>",
87	                    None,
88	                    &Value::Null,
89	                    crate::audit::ResultClass::ParseError,
90	                    started.elapsed().as_micros(),
91	                );
92	                resp
93	            }
94	            Ok(req) => {
95	                if req.jsonrpc != "2.0" {
96	                    let resp = JsonRpcResponse::err(
97	                        req.id.clone().unwrap_or(Value::Null),
98	                        -32600,
99	                        "Invalid Request: jsonrpc must be '2.0'",
100	                    );
101	                    crate::audit::log_intent(
102	                        &req.method,
103	                        req.id.as_ref(),
104	                        &req.params,
105	                        crate::audit::ResultClass::InvalidParams,
106	                        started.elapsed().as_micros(),
107	                    );
108	                    resp
109	                } else {
110	                    let id = req.id.clone().unwrap_or(Value::Null);
111	                    let method = req.method.clone();
112	                    let req_id_clone = req.id.clone();
113	                    let params_clone = req.params.clone();
114	                    let resp = dispatch(req).await.unwrap_or_else(|e| {
115	                        error!("Dispatch error: {}", e);
116	                        JsonRpcResponse::err(id, -32603, format!("Internal error: {}", e))
117	                    });
118	                    crate::audit::log_intent(
119	                        &method,
120	                        req_id_clone.as_ref(),
121	                        &params_clone,
122	                        classify(&resp),
123	                        started.elapsed().as_micros(),
124	                    );
125	                    resp
126	                }
127	            }
128	        };
129	
130	        let mut response_str = serde_json::to_string(&response)?;
131	        response_str.push('\n');
132	        writer.write_all(response_str.as_bytes()).await?;
133	        writer.flush().await?;
134	    }
135	
136	    Ok(())
137	}
138	
139	/// Map a JSON-RPC response to an audit result class.
140	fn classify(resp: &JsonRpcResponse) -> crate::audit::ResultClass {
141	    if let Some(err) = &resp.error {
142	        return match err.code {
143	            -32601 => crate::audit::ResultClass::MethodNotFound,
144	            -32602 => crate::audit::ResultClass::InvalidParams,
145	            -32700 => crate::audit::ResultClass::ParseError,
146	            _ => crate::audit::ResultClass::Err,
147	        };
148	    }
149	    // Look inside the result envelope for a sentinel status field.
150	    if let Some(result) = &resp.result {
151	        if let Some(status) = result.get("status").and_then(|v| v.as_str()) {
152	            return match status {
153	                "requires_cow_approval" => crate::audit::ResultClass::CowRequired,
154	                "unavailable" => crate::audit::ResultClass::Unavailable,
155	                "refused" => crate::audit::ResultClass::Refused,
156	                "err" => crate::audit::ResultClass::Err,
157	                _ => crate::audit::ResultClass::Ok,
158	            };
159	        }
160	    }
161	    crate::audit::ResultClass::Ok
162	}
163	
164	async fn dispatch(mut req: JsonRpcRequest) -> Result<JsonRpcResponse> {
165	    let id = req.id.clone().unwrap_or(Value::Null);
166	    info!("method={} id={}", req.method, id);
167	
168	    // Sequence matters: known-method check FIRST (so unknown methods return
169	    // -32601 Method not found), then schema validation (-32602 Invalid params),
170	    // then execution. This keeps error codes faithful to JSON-RPC 2.0 §5.1.
171	    if !is_known_method(&req.method) {
172	        return Ok(JsonRpcResponse::err(
173	            id,
174	            -32601,
175	            format!("Method not found: {}", req.method),
176	        ));
177	    }
178	
179	    // JSON-RPC 2.0 § 4.1: `params` MAY be omitted. We coerce `null` (the
180	    // serde_json default for a missing field) to `{}` so schemas of shape
181	    // `{type: object, additionalProperties: false}` accept no-arg calls.
182	    if req.params.is_null() {
183	        req.params = Value::Object(serde_json::Map::new());
184	    }
185	
186	    // INV-4: every dispatched call's params are validated against its schema
187	    // before the tool function runs. Schemas are embedded at compile time
188	    // (see schema.rs) so this check cannot be bypassed at runtime.
189	    if let Err(e) = crate::schema::validate(&req.method, &req.params) {
190	        return Ok(JsonRpcResponse::err(id, -32602, format!("Invalid params: {}", e)));
191	    }
192	
193	    let result = match req.method.as_str() {
194	        // MCP discovery — returns the full tool catalogue
195	        "tools/list" => tools::list_all(),
196	
197	        // System read-only tools
198	        "system.status"  => tools::system::status().await,
199	        "system.uptime"  => tools::system::uptime().await,
200	        "system.cpu"     => tools::system::cpu().await,
201	        "system.memory"  => tools::system::memory().await,
202	        "system.disk"    => tools::system::disk().await,
203	
204	        // Process read-only tools
205	        "process.list"    => tools::process::list().await,
206	        "process.inspect" => {
207	            // Safe to unwrap: schema validation above guarantees `pid` is an
208	            // integer in the valid range.
209	            let pid = req.params["pid"].as_u64().expect("schema-validated") as u32;
210	            tools::process::inspect(pid).await
211	        }
212	
213	        // Filesystem read-only tools (Tier 0). Path validation is in fs::validate;
214	        // openat2(RESOLVE_BENEATH) is the kernel-side gate inside the tool fn.
215	        "fs.read" => {
216	            let path = req.params["path"].as_str().expect("schema-validated");
217	            tools::fs::read(path).await
218	        }
219	        "fs.list" => {
220	            let path = req.params["path"].as_str().expect("schema-validated");
221	            tools::fs::list(path).await
222	        }
223	        "fs.stat" => {
224	            let path = req.params["path"].as_str().expect("schema-validated");
225	            tools::fs::stat(path).await
226	        }
227	        "fs.write" => {
228	            let path = req.params["path"].as_str().expect("schema-validated");
229	            let content = req.params["content"].as_str().expect("schema-validated");
230	            let mode = req.params.get("mode").and_then(|v| v.as_u64()).map(|m| m as u32);
231	            tools::fs::write(path, content, mode).await
232	        }
233	        "fs.delete" => {
234	            let path = req.params["path"].as_str().expect("schema-validated");
235	            tools::fs::delete(path).await
236	        }
237	
238	        // systemd unit control via D-Bus (M1.6). Graceful degradation on bus
239	        // failure happens inside the tool fn — never bubbles up as -32603.
240	        "service.start" => {
241	            let unit = req.params["unit"].as_str().expect("schema-validated");
242	            tools::service::start(unit).await
243	        }
244	        "service.stop" => {
245	            let unit = req.params["unit"].as_str().expect("schema-validated");
246	            tools::service::stop(unit).await
247	        }
248	        "service.restart" => {
249	            let unit = req.params["unit"].as_str().expect("schema-validated");
250	            tools::service::restart(unit).await
251	        }
252	        "service.logs" => {
253	            let unit = req.params["unit"].as_str().expect("schema-validated");
254	            let lines = req.params.get("lines").and_then(|v| v.as_u64()).unwrap_or(200);
255	            tools::service::logs(unit, lines).await
256	        }
257	
258	        // Network read-only (M1.7). Write-side tools (firewall, dns.set) are
259	        // not yet exposed in the catalogue; they land in Phase 5.
260	        "network.status"   => tools::network::status().await,
261	        "network.dns.read" => tools::network::dns_read().await,
262	
263	        // Package introspection (M1.8). Query is direct; install/remove/upgrade
264	        // always return a COW ticket — Phase 3 commits via apt-get inside an overlay.
265	        "package.query" => {
266	            let pattern = req.params["pattern"].as_str().expect("schema-validated");
267	            tools::package::query(pattern).await
268	        }
269	        "package.install" => {
270	            let package = req.params["package"].as_str().expect("schema-validated");
271	            tools::package::install(package).await
272	        }
273	        "package.remove" => {
274	            let package = req.params["package"].as_str().expect("schema-validated");
275	            tools::package::remove(package).await
276	        }
277	        "package.upgrade" => {
278	            let package = req.params["package"].as_str().expect("schema-validated");
279	            tools::package::upgrade(package).await
280	        }
281	
282	        // Unreachable: is_known_method() gates this match above.
283	        other => unreachable!("dispatch reached unknown method '{}' after is_known_method check", other),
284	    };
285	
286	    match result {
287	        Ok(value) => Ok(JsonRpcResponse::ok(id, value)),
288	        Err(e) => Ok(JsonRpcResponse::err(id, -32603, e.to_string())),
289	    }
290	}
291	
292	/// Returns true if `method` is one of the methods this dispatcher routes.
293	/// Single source of truth for both the -32601 check and the match arms.
294	fn is_known_method(method: &str) -> bool {
295	    matches!(method,
296	        "tools/list"
297	        | "system.status" | "system.uptime" | "system.cpu" | "system.memory" | "system.disk"
298	        | "process.list" | "process.inspect"
299	        | "fs.read" | "fs.list" | "fs.stat" | "fs.write" | "fs.delete"
300	        | "service.start" | "service.stop" | "service.restart" | "service.logs"
301	        | "network.status" | "network.dns.read"
302	        | "package.query" | "package.install" | "package.remove" | "package.upgrade"
303	    )
304	}
