use serde_json::{json, Value};

use crate::schema;

pub mod fs;
pub mod network;
pub mod package;
pub mod process;
pub mod service;
pub mod system;

/// Static descriptor for one tool entry in the discovery catalogue.
/// The actual JSON Schema for params is pulled from `schema::schema_json()`
